app.get('/healthz', async (req, res) => {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.error('DATABASE_URL not set');
    return res.status(503).json({ db: 'error' });
  }
  try {
    const { hostname, port } = new URL(dbUrl);
    // Default Postgres port if not specified
    const pgPort = port || '5432';
    await new Promise((resolve, reject) => {
      const socket = net.createConnection({ host: hostname, port: pgPort }, () => {
        socket.end();
        resolve();
      });
      socket.setTimeout(2000);
      socket.on('error', reject);
      socket.on('timeout', () => {
        socket.destroy();
        reject(new Error('timeout'));
      });
    });
    res.status(200).json({ db: 'ok' });
  } catch (err) {
    console.error('Healthz DB check failed:', err.message);
    res.status(503).json({ db: 'error' });
  }
});

